	@ParameterizedTest(name = "{0}: {1}")
	@MethodSource("families")
	void sameExpressionGivesConsistentResultsInEveryPlacement(String family, String expression, String unbound) {
		Map<String, Value> fromSelect = valuesByRow(
				query("SELECT ?x (" + expression + " AS ?r) WHERE { " + PATTERN + " }"));
		assertThat(fromSelect).as(family + " SELECT expression").hasSize(4);
		assertThat(fromSelect.values()).as(family + " at least one row evaluates").anyMatch(v -> v != null);

		Map<String, Value> fromBind = valuesByRow(
				query("SELECT ?x ?r WHERE { " + PATTERN + " BIND(" + expression + " AS ?r) }"));
		assertThat(fromBind).as(family + " BIND").isEqualTo(fromSelect);

		Map<String, Value> fromSubSelect = valuesByRow(
				query("SELECT ?x ?r WHERE { { SELECT ?x (" + expression + " AS ?r) WHERE { " + PATTERN + " } } }"));
		assertThat(fromSubSelect).as(family + " sub-select").isEqualTo(fromSelect);

		for (Value expected : new ArrayList<>(fromSelect.values())) {
			if (expected == null) {
				continue;
			}
			List<String> matching = new ArrayList<>();
			fromSelect.forEach((x, v) -> {
				if (expected.equals(v)) {
					matching.add(x);
				}
			});
			List<BindingSet> filtered = query("SELECT ?x WHERE { " + PATTERN + " FILTER(" + expression + " = "
					+ NTriplesUtil.toNTriplesString(expected) + ") } ORDER BY ?x");
			assertThat(filtered).extracting(bs -> bs.getValue("x").stringValue())
					.as(family + " FILTER(" + expression + " = " + expected + ")")
					.containsExactlyElementsOf(matching);
		}

		List<String> orderedByExpression = column(
				query("SELECT ?x WHERE { " + PATTERN + " } ORDER BY (" + expression + ") ?x"), "x");
		List<String> orderedByBoundResult = column(
				query("SELECT ?x WHERE { " + PATTERN + " BIND(" + expression + " AS ?r) } ORDER BY ?r ?x"), "x");
		assertThat(orderedByExpression).as(family + " ORDER BY").hasSize(4).isEqualTo(orderedByBoundResult);

		Map<Value, Long> expectedGroups = new HashMap<>();
		fromSelect.values().forEach(v -> expectedGroups.merge(v, 1L, Long::sum));
		Map<Value, Long> groups = new HashMap<>();
		for (BindingSet row : query(
				"SELECT ?k (COUNT(?x) AS ?c) WHERE { " + PATTERN + " } GROUP BY (" + expression + " AS ?k)")) {
			groups.merge(row.getValue("k"), ((Literal) row.getValue("c")).longValue(), Long::sum);
		}
		assertThat(groups).as(family + " GROUP BY key").isEqualTo(expectedGroups);
	}

	@ParameterizedTest(name = "{0}: {2}")
	@MethodSource("families")
	void unboundArgumentLeavesBindVariableUnboundAndQueryContinues(String family, String expression,
			String unbound) {
		List<BindingSet> rows = query("SELECT ?x ?n ?r WHERE { " + PATTERN + " OPTIONAL { ?x ex:missing ?m }"
				+ " BIND(" + unbound + " AS ?r) } ORDER BY ?x");
		assertThat(rows).as(family + " rows survive the failed BIND").hasSize(4);
		for (BindingSet row : rows) {
			assertThat(row.hasBinding("x")).isTrue();
			assertThat(row.hasBinding("n")).isTrue();
			assertThat(row.hasBinding("r")).as(family + " ?r stays unbound for " + row.getValue("x")).isFalse();
		}
		// the same failed expression in FILTER drops every row instead of raising
		assertThat(query("SELECT ?x WHERE { " + PATTERN + " OPTIONAL { ?x ex:missing ?m } FILTER(" + unbound
				+ " = 1) }")).as(family + " FILTER on unbound argument").isEmpty();
	}

	@Test
	void everyFunctionTypeInOneSelectEvaluates() {
		// Scalars of every family in BIND, a window function and a custom aggregate in sub-selects, and a magic
		// property: one row per tag. The plan asks for completion under -Xmx256m; the Surefire heap is fixed by the
		// build, so this test asserts completion and the result shape in-process.
		List<BindingSet> rows = query("SELECT * WHERE {"
				+ " { SELECT ?x ?n ?s ?d ?doc (winf:rowNumber(winf:orderBy(?x)) AS ?rn) WHERE { " + PATTERN + " } }"
				+ " { SELECT (agg:median(?n2) AS ?med) (agg:countIf(?n2 > 5) AS ?big) WHERE { ?y ex:n ?n2 } }"
				+ " (?s \",\") strf:split (?tag)"
				+ " BIND(mathf:pow(?n, 2) AS ?p) BIND(strf:reverse(?tag) AS ?rev) BIND(dtf:dayOfYear(?d) AS ?doy)"
				+ " BIND(textf:levenshtein(?tag, \"alpha\") AS ?lev) BIND(jsonf:jsonValue(?doc, \"$.k\") AS ?jv)"
				+ " BIND(arrf:arrayLength(strf:split(?s, \",\")) AS ?len) BIND(bitf:bitAnd(?n, 6) AS ?band)"
				+ " BIND(encf:toHex(?tag) AS ?hex) BIND(miscf:nullIf(?n, 10) AS ?nn)"
				+ " } ORDER BY ?x ?tag");
		assertThat(rows).hasSize(8);
		List<String> allBound = List.of("x", "n", "s", "d", "doc", "rn", "med", "big", "tag", "p", "rev", "doy",
				"lev", "jv", "len", "band", "hex");
		for (BindingSet row : rows) {
			for (String name : allBound) {
				assertThat(row.hasBinding(name)).as(name + " in " + row).isTrue();
			}
			boolean ten = row.getValue("n").stringValue().equals("10");
			assertThat(row.hasBinding("nn")).as("nullIf for " + row.getValue("x")).isEqualTo(!ten);
		}
		assertThat(column(rows, "tag")).containsExactly("alpha", "beta", "gamma", "alpha", "beta", "delta", "eps",
				"zeta");
		assertThat(column(rows, "med")).containsOnly("4.5");
		assertThat(column(rows, "big")).containsOnly("2");
		assertThat(column(rows, "rn")).containsExactly("1", "1", "2", "3", "3", "4", "4", "4");
	}

	@Test
	void cachedFormattersAndMacsAreSafeUnderConcurrentEvaluation() throws Exception {
		int threads = 16;
		int iterations = 300;
		FunctionRegistry registry = FunctionRegistry.getInstance();
		Function regexpExtract = function(registry, STRF.regexpExtract.stringValue());
		Function dateFormat = function(registry, DTF.dateFormat.stringValue());
		Function parseDate = function(registry, DTF.parseDate.stringValue());
		Function decimalFormat = function(registry, MATHF.decimalFormat.stringValue());
		Function hmac = function(registry, ENCF.hmac.stringValue());
		ValueFactory vf = SimpleValueFactory.getInstance();
		Literal dateTime = vf.createLiteral("2024-03-05T10:20:30Z", XSD.DATETIME);

		List<String> failures = new CopyOnWriteArrayList<>();
		CyclicBarrier start = new CyclicBarrier(threads);
		ExecutorService pool = Executors.newFixedThreadPool(threads);
		try {
			List<Future<?>> futures = new ArrayList<>();
			for (int t = 0; t < threads; t++) {
				int i = t;
				futures.add(pool.submit(() -> {
					// every thread uses its own pattern, key and inputs so shared caches hold distinct entries
					String regexSource = "v" + i + "=" + (i * 7);
					String regex = "v" + i + "=([0-9]+)";
					String datePattern = "'T" + i + "' yyyy/MM/dd HH:mm";
					String expectedDate = DateTimeFormatter.ofPattern(datePattern, Locale.ROOT)
							.format(LocalDateTime.of(2024, 3, 5, 10, 20, 30));
					String day = String.format(Locale.ROOT, "%02d", i + 1);
					String parseSource = "2024-03-" + day + "#" + i;
					String parsePattern = "yyyy-MM-dd'#" + i + "'";
					BigDecimal number = new BigDecimal("1234.5").add(BigDecimal.valueOf(i));
					String decimalPattern = "#,##0." + "0".repeat(1 + i % 4);
					String expectedDecimal = new DecimalFormat(decimalPattern,
							DecimalFormatSymbols.getInstance(Locale.ROOT)).format(number);
					String message = "message-" + i;
					String key = "key-" + i;
					String expectedHmac = hmacSha256Hex(key, message);
					start.await();
					for (int n = 0; n < iterations; n++) {
						check(failures, i, "regexpExtract", String.valueOf(i * 7), regexpExtract.evaluate(vf,
								vf.createLiteral(regexSource), vf.createLiteral(regex), vf.createLiteral(1)));
						check(failures, i, "dateFormat", expectedDate,
								dateFormat.evaluate(vf, dateTime, vf.createLiteral(datePattern)));
						check(failures, i, "parseDate", "2024-03-" + day,
								parseDate.evaluate(vf, vf.createLiteral(parseSource), vf.createLiteral(parsePattern)));
						check(failures, i, "decimalFormat", expectedDecimal, decimalFormat.evaluate(vf,
								vf.createLiteral(number), vf.createLiteral(decimalPattern)));
						check(failures, i, "hmac", expectedHmac,
								hmac.evaluate(vf, vf.createLiteral(message), vf.createLiteral(key)));
					}
					return null;
				}));
			}
			for (Future<?> future : futures) {
				future.get(2, TimeUnit.MINUTES);
			}
		} finally {
			pool.shutdownNow();
		}
		assertThat(failures).isEmpty();
	}

	private static Function function(FunctionRegistry registry, String iri) {
		Optional<Function> function = registry.get(iri);
		assertThat(function).as(iri).isPresent();
		return function.get();
	}

	private static void check(List<String> failures, int thread, String name, String expected, Value actual) {
		if (actual == null || !expected.equals(actual.stringValue())) {
			failures.add("thread " + thread + " " + name + ": expected " + expected + " but was " + actual);
		}
	}

	private static String hmacSha256Hex(String key, String message) {
		try {
			Mac mac = Mac.getInstance("HmacSHA256");
			mac.init(new SecretKeySpec(key.getBytes(StandardCharsets.UTF_8), "HmacSHA256"));
			StringBuilder hex = new StringBuilder();
			for (byte b : mac.doFinal(message.getBytes(StandardCharsets.UTF_8))) {
				hex.append(String.format(Locale.ROOT, "%02x", b));
			}
			return hex.toString();
		} catch (Exception e) {
			throw new AssertionError(e);
		}
	}

	/** Maps the ?x of each row to its ?r (null when unbound), failing on duplicate subjects. */
	static Map<String, Value> valuesByRow(List<BindingSet> rows) {
		Map<String, Value> values = new LinkedHashMap<>();
		for (BindingSet row : rows) {
			String x = row.getValue("x").stringValue();
			assertThat(values.containsKey(x)).as("duplicate row for " + x).isFalse();
			values.put(x, row.hasBinding("r") ? row.getValue("r") : null);
		}
		return Collections.unmodifiableMap(values);
	}

	static List<String> column(List<BindingSet> rows, String var) {
		List<String> values = new ArrayList<>();
		for (BindingSet row : rows) {
			values.add(row.hasBinding(var) ? row.getValue(var).stringValue() : null);
		}
		return values;
	}
